SELECT *, DENSE_RANK() OVER (ORDER BY stock_qty ASC NULLS FIRST) AS stock_qty_dense_rank, FIRST_VALUE(price) IGNORE NULLS OVER (PARTITION BY brand ORDER BY launch_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_price, AVG(stock_qty) OVER w_hist AS stock_qty_avg_2_prior FROM products WINDOW w_hist AS (PARTITION BY supplier_id ORDER BY cost ASC, id ASC ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING);
